const CAREER_BY_ID = new Map(CAREERS.map(x => [x.id, x]));
const GOV_BY_ID = new Map(GOV_JOBS.map(x => [x.id, x]));

// Words too common in this domain to tell two careers apart.
const STOP = new Set(["a","an","the","and","or","of","for","to","in","on","is","are",
  "what","which","how","do","does","i","me","my","you","career","careers","job","jobs",
  "become","becoming","work","working","should","can","about","best","good","after"]);

function terms(text){
  return String(text || "")
    .toLowerCase()
    .replace(/[^a-z0-9+#.\s]/g, " ")
    .split(/\s+/)
    .filter(w => w.length > 1 && !STOP.has(w));
}

// Everything about a record that a query might legitimately match.
function haystack(record){
  return [record.title, record.sector, record.work, record.qualifications,
          record.exams, record.style, record.setting,
          (record.skills || []).join(" "), (record.streams || []).join(" "),
          record.category, record.criteria, record.note]
    .filter(Boolean).join(" ").toLowerCase();
}

/*
  Deliberately a keyword score rather than an embedding.

  The queries this serves are short and concrete — "chartered accountant",
  "what does an actuary earn", "jobs after B.Sc that aren't medicine" —
  and a title match is worth more than semantic proximity for all of them.
  An embedding index would be a second service to run and to keep in sync
  for an answer that is not better here.
*/
function scoreRecord(record, words, hay){
  let score = 0;
  const title = String(record.title || "").toLowerCase();
  for(const word of words){
    if(title.includes(word)) score += 10;
    else if(hay.includes(word)) score += 2;
  }
  return score;
}

function searchCareers(query, options){
  const opts = options || {};
  const words = terms(query);
  const wanted = (opts.themes || []).filter(Boolean);
  const limit = Math.min(Math.max(Number(opts.limit) || 4, 1), 8);

  if(!words.length && !wanted.length) return [];

  return CAREERS
    .map(record => {
      let score = words.length ? scoreRecord(record, words, haystack(record)) : 0;
      // A theme match is a nudge, never the whole answer: somebody asking
      // about accountancy should get accountancy even if their profile
      // leans Artistic.
      if(wanted.length && record.themes.some(t => wanted.indexOf(t) !== -1)) score += 3;
      return { record, score };
    })
    .filter(row => row.score > 0)
    .sort((a, b) => b.score - a.score || a.record.title.localeCompare(b.record.title))
    .slice(0, limit)
    .map(row => row.record);
}

function searchGovJobs(query, options){
  const opts = options || {};
  const words = terms(query);
  const limit = Math.min(Math.max(Number(opts.limit) || 4, 1), 8);
  if(!words.length) return [];

  return GOV_JOBS
    .map(record => ({ record, score: scoreRecord(record, words, haystack(record)) }))
    .filter(row => row.score > 0)
    .sort((a, b) => b.score - a.score || a.record.title.localeCompare(b.record.title))
    .slice(0, limit)
    .map(row => row.record);
}

function getCareer(id){ return CAREER_BY_ID.get(String(id)) || null; }
function getGovJob(id){ return GOV_BY_ID.get(String(id)) || null; }

/*
  The compact list that goes in the cached system prompt, so the agent
  knows the shape of what it may talk about without carrying the text of
  it. Sorted so the cached prefix is byte-stable between deploys.
*/
function catalogue(){
  const careers = CAREERS
    .slice()
    .sort((a, b) => a.id.localeCompare(b.id))
    .map(c => c.id + " | " + c.title + " | " + c.sector + " | " + c.themes.join(""));
  const gov = GOV_JOBS
    .slice()
    .sort((a, b) => a.id.localeCompare(b.id))
    .map(g => g.id + " | " + g.title + " | " + g.category);
  return { careers, gov };
}

module.exports = {
  CAREERS, GOV_JOBS,
  searchCareers, searchGovJobs,
  getCareer, getGovJob,
  catalogue, terms
};
